"""Abstract Framework Adapter Interface for SQL RL training.

Decouples policy optimization frameworks (SkyRL-Agent, veRL, TRL, etc.)
from the database execution sandbox and verifiable reward engine.
"""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Any

from omegaconf import DictConfig

from ask_the_database.rewards.rubric import SQLRewardRubric


@dataclass(frozen=True)
class RolloutBatch:
    """Standardized batch of rollouts generated by an actor policy."""

    prompts: list[str]
    completions: list[str]
    gold_sqls: list[str]
    db_paths: list[str]
    metadata: list[dict[str, Any]] = field(default_factory=list)

    def __post_init__(self) -> None:
        """Validate invariant that all parallel sequences have identical length."""
        n = len(self.prompts)
        if not (
            len(self.completions) == n and len(self.gold_sqls) == n and len(self.db_paths) == n
        ):
            raise ValueError(
                f"Batch lengths mismatch: prompts={len(self.prompts)}, "
                f"completions={len(self.completions)}, "
                f"gold_sqls={len(self.gold_sqls)}, "
                f"db_paths={len(self.db_paths)}"
            )
        if self.metadata and len(self.metadata) != n:
            raise ValueError(
                f"Metadata length ({len(self.metadata)}) does not match batch size ({n})"
            )

    @property
    def batch_size(self) -> int:
        """Return the number of rollouts in the batch."""
        return len(self.prompts)


class BaseRLAdapter(ABC):
    """Abstract interface isolating the RL engine from the SQL scientific core."""

    def __init__(self, config: DictConfig, rubric: SQLRewardRubric) -> None:
        self.cfg = config
        self.rubric = rubric

    @abstractmethod
    def initialize_models(self) -> None:
        """Initialize actor, critic (if applicable), and reference policy."""
        pass

    @abstractmethod
    def compute_rewards(self, batch: RolloutBatch) -> list[float]:
        """Compute scalar rewards for each completion in the batch using the rubric."""
        pass

    @abstractmethod
    def train_step(self, batch: RolloutBatch) -> dict[str, float]:
        """Execute policy optimization step and return telemetry metrics."""
        pass

    @abstractmethod
    def save_checkpoint(self, output_dir: str) -> None:
        """Persist policy weights and LoRA adapters."""
        pass
